solution:
def ages(capture,read_done,decide_done,tap_done):
    assert capture<=read_done<=decide_done<=tap_done, 'Event times must be ordered on one clock'
    return decide_done-read_done,tap_done-capture

tests:
assert ages(1000,1040,1060,1090)==(20,90), 'Separate model latency from observation age'
assert ages(0,0,0,0)==(0,0), 'Equal event times are allowed'
try:
    ages(10,9,11,12)
except AssertionError:
    pass
else:
    assert False, 'Reject inconsistent event order'

